import {controller, target} from '@github/catalyst'

@controller('review-thread-collapsible')
export class ReviewThreadCollapsibleElement extends HTMLElement {
  @target declare button: HTMLButtonElement
  @target declare body: HTMLElement

  toggle() {
    const opening = !!this.body.hidden // 'until-found' is valid here, which we can treat as a not-hidden
    this.body.hidden = !opening
    this.button.setAttribute('aria-expanded', String(opening))
    this.classList.toggle('open', opening)

    if (opening) this.#loadDeferredContent()
  }

  // Idempotent: opens the thread if collapsed. Used by deep-link / hash-change
  // flows that need to reveal a specific comment. `toggle()` already loads any
  // deferred content on open, and an already-open thread has nothing to load.
  open() {
    if (this.body.hidden) this.toggle()
  }

  preload() {
    this.#loadDeferredContent()
  }

  #loadDeferredContent() {
    const url = this.getAttribute('data-deferred-content-url')
    if (!url) return

    // Validate the URL is a same-origin path (server-generated by Rails path helpers)
    let parsed: URL
    try {
      parsed = new URL(url, window.location.origin)
    } catch {
      return
    }
    if (parsed.origin !== window.location.origin) return
    if (parsed.hash) return
    // Ensure the pathname is a root-relative, well-formed path without dangerous characters
    if (!parsed.pathname.startsWith('/') || /[\r\n<>]/.test(parsed.pathname)) return

    const safeSrc = `${parsed.pathname}${parsed.search}`
    // Allow only typical URL characters to prevent HTML/meta-character injection
    const SAFE_URL_PATTERN = /^[A-Za-z0-9\-._~:/?#[\]@!$&'()*+,;=%]*$/
    if (!SAFE_URL_PATTERN.test(safeSrc)) return

    const fragment = this.querySelector('include-fragment')
    if (fragment && !fragment.getAttribute('src')) {
      fragment.setAttribute('src', safeSrc)
      this.removeAttribute('data-deferred-content-url')
    }
  }
}
